/**
 * setFlowVariables
 * ----------------
 * Type-only helper that assigns several Flow variables in one go while keeping
 * full compile-time safety.
 *
 *
 * Rules
 * • `_definition` may be either the flow-execution ID (`Now.ID.…`) or the same
 *   ID wrapped in an object that also carries an `annotation` string.
 * • `_variables` is the schema returned by {@link FlowVariables}.
 * • `_values` must be a subset of `_variables`; each supplied value must be
 *   assignable to the corresponding variable type (string values are permitted
 *   for template expressions).
 *
 * This helper is erased at runtime – it only influences the TypeScript
 * type-checker.
 *
 * @param _definition  Flow execution identifier (+ optional annotation).
 * @param _variables   Schema produced by {@link FlowVariables}.
 * @param _values      Partial record of variable assignments.
 */
import type { FlowSchemaType, FlowValueType } from '../FlowTypes';
import type { FlowVariableDefinition } from '../FlowVariables';
export declare function SetFlowVariables<T extends FlowVariableDefinition, S extends Record<string, FlowValueType>>(_definition: T, _variables: FlowSchemaType<S>, _values: {
    [K in keyof FlowSchemaType<S>]?: Exclude<FlowSchemaType<S>[K] | string, null | undefined>;
}): {
    type: 'setflowvariables';
};
